// Multi-job drip engine: touches ⑱-㉒ + no-show rebook ㉗
const t=new Date().toISOString().slice(0,10);const td=new Date(t);
const wa=(p,m)=>`https://wa.me/${p}?text=${encodeURIComponent(m)}`;
const DRIP={1:'value: one specific quick-win idea for their niche',3:'case study: similar client result',7:'offer: free 20-min growth audit',14:'last touch: leaving the door open, no pressure'};
let out=[];
for(const it of items){const r=it.json;if(!r.Phone||['Won','Lost'].includes(r.Stage))continue;
const age=Math.round((td-new Date(r.Date))/864e5);
if(r.LastTouch===t)continue;
if(DRIP[age])out.push(`• D${age} ${r.Name} (${r.Niche}): ${DRIP[age]} → ${wa(r.Phone,'Hi '+r.Name+'! ')} (write per pitch: ${r.Pitch})`);
if(age>21&&r.Stage==='New')out.push(`• 💤 REVIVE ${r.Name}: AI revival — send a fresh angle, niche=${r.Niche}`);
if(r.Stage==='NoShow')out.push(`• 📅 REBOOK ${r.Name}: ${wa(r.Phone,'Hi '+r.Name+'! We missed you — shall we find a better time?')}`);}
return [{ json: { text: out.length?'🧲 TODAY\'S ACQUISITION TOUCHES:\n'+out.slice(0,25).join('\n'):'✅ No touches due.' } }];
